import{_ as l,o as i,c as e,a6 as n}from"./chunks/framework.BlDtR6jM.js";const f=JSON.parse('{"title":"羁绊与生活系统 (Social Links & Life Sim)","description":"","frontmatter":{"readingTime":"6 min read"},"headers":[],"relativePath":"项目实践/JRPG/A_角色与成长/生活与羁绊/羁绊与生活系统.md","filePath":"项目实践/JRPG/A_角色与成长/生活与羁绊/羁绊与生活系统.md"}'),a={name:"项目实践/JRPG/A_角色与成长/生活与羁绊/羁绊与生活系统.md"};function r(s,t,o,g,d,u){return i(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="羁绊与生活系统-social-links-life-sim" tabindex="-1">羁绊与生活系统 (Social Links &amp; Life Sim) <a class="header-anchor" href="#羁绊与生活系统-social-links-life-sim" aria-label="Permalink to &quot;羁绊与生活系统 (Social Links &amp; Life Sim)&quot;">​</a></h1><blockquote><p><strong>设计灵感</strong>：参考《女神异闻录》(Persona) 的 COOP 系统与《传说系列》(Tales of) 的小剧场。 <strong>核心目标</strong>：建立玩家与角色的情感连接，让数值成长具有叙事动力。</p></blockquote><hr><h2 id="_1-羁绊等级-bond-rank" tabindex="-1">1. 羁绊等级 (Bond Rank) <a class="header-anchor" href="#_1-羁绊等级-bond-rank" aria-label="Permalink to &quot;1. 羁绊等级 (Bond Rank)&quot;">​</a></h2><p>每个队友拥有 <strong>Rank 1 ~ Rank 10</strong> 的羁绊等级。</p><h3 id="_1-1-升级机制" tabindex="-1">1.1 升级机制 <a class="header-anchor" href="#_1-1-升级机制" aria-label="Permalink to &quot;1.1 升级机制&quot;">​</a></h3><ul><li><strong>Rank 1~3 (相识)</strong>： <ul><li><strong>条件</strong>：主线剧情自动解锁，或初次入队。</li><li><strong>奖励</strong>：解锁角色基础档案，战斗中可使用“换人”功能。</li></ul></li><li><strong>Rank 4~6 (信赖)</strong>： <ul><li><strong>条件</strong>：完成特定<strong>羁绊任务 (Bond Quest)</strong>，平时对话选对选项，赠送喜爱礼物。</li><li><strong>奖励</strong>： <ul><li>解锁 <strong>[被动技能]</strong>（如朱利安的“商店折扣”，林晚晴的“战斗后自动回血”）。</li><li>解锁 <strong>[援护格挡]</strong>（战斗中概率自动为主角挡刀）。</li></ul></li></ul></li><li><strong>Rank 7~9 (挚友/知己)</strong>： <ul><li><strong>条件</strong>：完成角色专属的<strong>长篇支线</strong>（通常涉及角色过去的阴影或秘密）。</li><li><strong>奖励</strong>： <ul><li>解锁 <strong>[组合技 (Combo Skill)]</strong>。</li><li>解锁 <strong>[克服弱点]</strong>（如阿伊莎不再畏惧光属性）。</li></ul></li></ul></li><li><strong>Rank 10 (生死之交/恋人)</strong>： <ul><li><strong>条件</strong>：最终羁绊事件（需关键道具）。</li><li><strong>奖励</strong>： <ul><li>角色立绘变化（觉醒形态）。</li><li>最强专属武器/饰品解锁。</li><li>结局改变。</li></ul></li></ul></li></ul><hr><h2 id="_2-小剧场系统-skits" tabindex="-1">2. 小剧场系统 (Skits) <a class="header-anchor" href="#_2-小剧场系统-skits" aria-label="Permalink to &quot;2. 小剧场系统 (Skits)&quot;">​</a></h2><h3 id="_2-1-触发机制" tabindex="-1">2.1 触发机制 <a class="header-anchor" href="#_2-1-触发机制" aria-label="Permalink to &quot;2.1 触发机制&quot;">​</a></h3><p>在屏幕左下角出现提示按键（如 <code>Tap Z</code>），点击后播放一段类似漫画分镜或立绘对话的短剧。</p><ul><li><strong>场景触发</strong>： <ul><li>到达新城镇/迷宫。</li><li>在寒冷/炎热地区停留过久。</li></ul></li><li><strong>状态触发</strong>： <ul><li>全员 HP &lt; 20% 险胜后（互相吐槽太狼狈）。</li><li>获得稀有食材后（讨论怎么煮）。</li><li>林晚晴升级学会新技能后（夸奖/自我怀疑）。</li></ul></li><li><strong>剧情触发</strong>： <ul><li>主线关键剧情后的“复盘会”。</li></ul></li></ul><h3 id="_2-2-内容分类" tabindex="-1">2.2 内容分类 <a class="header-anchor" href="#_2-2-内容分类" aria-label="Permalink to &quot;2.2 内容分类&quot;">​</a></h3><ul><li><strong>搞笑/日常</strong>：调节游戏节奏，展示角色反差萌（如高冷的阿伊莎其实怕虫子）。</li><li><strong>世界观补充</strong>：借角色之口介绍当地风俗、历史。</li><li><strong>提示/引导</strong>：玩家迷路或卡关时，队友给出建议。</li></ul><hr><h2 id="_3-据点生活-base-life" tabindex="-1">3. 据点生活 (Base Life) <a class="header-anchor" href="#_3-据点生活-base-life" aria-label="Permalink to &quot;3. 据点生活 (Base Life)&quot;">​</a></h2><h3 id="_3-1-飞空艇-移动基地" tabindex="-1">3.1 飞空艇/移动基地 <a class="header-anchor" href="#_3-1-飞空艇-移动基地" aria-label="Permalink to &quot;3.1 飞空艇/移动基地&quot;">​</a></h3><p>随着剧情（上海篇结束）获得移动载具（如蒸汽飞艇“天工号”）。</p><ul><li><strong>功能区域</strong>： <ul><li><strong>舰桥</strong>：进行主线航行，陆明夷在此接收信号（支线）。</li><li><strong>工坊</strong>：朱利安常驻，进行装备改造、道具合成。</li><li><strong>医务室</strong>：林晚晴常驻，治疗重伤（清除永久 Debuff），种植草药。</li><li><strong>厨房</strong>：烹饪料理（提供全队 Buff），不同角色掌勺效果不同。</li><li><strong>休息舱</strong>：更换背景音乐 (BGM)，查看图鉴/回顾剧情。</li></ul></li></ul><h3 id="_3-2-互动事件" tabindex="-1">3.2 互动事件 <a class="header-anchor" href="#_3-2-互动事件" aria-label="Permalink to &quot;3.2 互动事件&quot;">​</a></h3><ul><li>在据点内，角色会有随机行为（如陈少秋在擦枪，伊万在喝酒）。</li><li>主动对话可触发“日常羁绊事件”（不消耗时间的轻度交互）。</li></ul><hr><h2 id="_4-时间流逝-time-system" tabindex="-1">4. 时间流逝 (Time System) <a class="header-anchor" href="#_4-时间流逝-time-system" aria-label="Permalink to &quot;4. 时间流逝 (Time System)&quot;">​</a></h2><p>虽然不采用严格的日历限制（避免玩家焦虑），但引入 <strong>[昼夜循环]</strong> 或 <strong>[章节间歇]</strong>。</p><ul><li><strong>昼夜影响</strong>： <ul><li><strong>白天</strong>：城镇 NPC 正常活动，商店开门。</li><li><strong>夜晚</strong>： <ul><li>怪物强度提升（出现“夜行种”）。</li><li>部分黑市商人出现。</li><li>阿伊莎的“潜行/暗杀”成功率提升。</li></ul></li></ul></li><li><strong>扎营 (Camping)</strong>： <ul><li>在野外存档点可以扎营，强制切换昼夜。</li><li>扎营时可以进行烹饪、观看小剧场。</li></ul></li></ul><hr><h2 id="_5-礼物系统-gifting" tabindex="-1">5. 礼物系统 (Gifting) <a class="header-anchor" href="#_5-礼物系统-gifting" aria-label="Permalink to &quot;5. 礼物系统 (Gifting)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">角色</th><th style="text-align:left;">喜好类型</th><th style="text-align:left;">厌恶类型</th><th style="text-align:left;">示例礼物</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>陈少秋</strong></td><td style="text-align:left;">机械零件、旧时代遗物</td><td style="text-align:left;">甜食</td><td style="text-align:left;">破碎的怀表、战前报纸</td></tr><tr><td style="text-align:left;"><strong>林晚晴</strong></td><td style="text-align:left;">医书、稀有草药</td><td style="text-align:left;">暴力兵器</td><td style="text-align:left;">《本草纲目残卷》、雪莲</td></tr><tr><td style="text-align:left;"><strong>朱利安</strong></td><td style="text-align:left;">咖啡、精密工具</td><td style="text-align:left;">迷信物品</td><td style="text-align:left;">进口咖啡豆、多功能扳手</td></tr><tr><td style="text-align:left;"><strong>阿伊莎</strong></td><td style="text-align:left;">历史文物、匕首</td><td style="text-align:left;">廉价饰品</td><td style="text-align:left;">殷商甲骨、大马士革钢</td></tr><tr><td style="text-align:left;"><strong>伊万</strong></td><td style="text-align:left;">烈酒、肉类</td><td style="text-align:left;">蔬菜</td><td style="text-align:left;">伏特加、烤全羊</td></tr></tbody></table><blockquote><p><strong>设计意图</strong>：通过这些生活化系统，让“蒸汽妖都”不仅仅是一个战斗背景，而是一个角色们真实生活的世界。</p></blockquote>',29)])])}const _=l(a,[["render",r]]);export{f as __pageData,_ as default};
